  "packages.onboarding.tours.builtin.sessionsDefinesTheDefaultModelRoleThinking": "Sitzungen definiert Standardmodell, -rolle, -Denkstufe und das schlanke Modell, falls ein Projekt keine eigene Vorgabe hat.",
  "packages.onboarding.tours.builtin.sessionSteps": "Sitzungsschritte",
  "packages.onboarding.tours.builtin.setALocalDateRepeatEveryNumber": "Legen Sie ein lokales Datum fest, wiederholen Sie den Vorgang alle paar Minuten oder verwenden Sie cron mit einer expliziten Zeitzone.",
  "packages.onboarding.tours.builtin.setBrowserLocalBasics": "Browser-lokale Grundeinstellungen festlegen",
  "packages.onboarding.tours.builtin.setTheGlobalModelFallback": "Globales Modell-Fallback festlegen",
  "packages.onboarding.tours.builtin.setWorkspaceWideWorkingRules": "Arbeitsregeln für den gesamten Arbeitsbereich festlegen",
  "packages.onboarding.tours.builtin.shareAControlledBrowser": "Einen kontrollierten Browser teilen",
  "packages.onboarding.tours.builtin.shortcuts": "Tastenkürzel",
  "packages.onboarding.tours.builtin.shortcutsCollectsCoreAndPluginProvidedActions": "Shortcuts fasst die vom System und den Plugins bereitgestellten Aktionen in einer bearbeitbaren Tastenkombination zusammen. Standardmäßig sind Mod+K für die Befehlspalette, Mod+P zum Suchen von Dateien und Mod+J für das Terminal belegt.",
  "packages.onboarding.tours.builtin.skipPromptsForTrustedSessions": "Aufforderungen für vertrauenswürdige Sitzungen überspringen",
  "packages.onboarding.tours.builtin.skipQueueOrRunInParallelWhen": "Überspringen, in die Warteschlange stellen oder parallel ausführen, wenn die vorherige Aufgabe noch nicht abgeschlossen ist.",
  "packages.onboarding.tours.builtin.snapshot": "Snapshot",
  "packages.onboarding.tours.builtin.startAdditionalTerminalsForServersTestsOr": "Starten Sie zusätzliche Terminals für Server, Tests oder einmalige Befehle und benennen Sie die einzelnen Registerkarten nach Bedarf um.",
  "packages.onboarding.tours.builtin.startEverySessionConsistently": "Jede Sitzung konsistent starten",
  "packages.onboarding.tours.builtin.startTheConfiguredPreviewSwitchAmongDiscovered": "Starten Sie die konfigurierte Vorschau, wechseln Sie zwischen den ermittelten Adressen und beenden Sie sie, wenn der Lauf abgeschlossen ist.",
  "packages.onboarding.tours.builtin.steerRedirectsTheActiveTurnQueueWaits": "Steer lenkt den aktiven Zug um, Queue wartet darauf und Interrupt bricht ihn vor dem Senden ab.",
  "packages.onboarding.tours.builtin.switchSessionActivityBetweenRelativeLabelsAnd": "Wechseln Sie die Sitzungsaktivität zwischen relativen Bezeichnungen und Uhrzeiten.",
  "packages.onboarding.tours.builtin.synthesizeSeveralModelDrafts": "Mehrere Modellentwürfe zusammenfassen",
  "packages.onboarding.tours.builtin.terminal": "Terminal",
  "packages.onboarding.tours.builtin.terminalOpensProjectScopedShellSessionsIn": "Terminal öffnet projektbezogene Shell-Sitzungen in einem Arbeitsbereichsfenster und stellt die Verbindung zu laufenden Terminals mit deren letzter Ausgabe wieder her.",
  "packages.onboarding.tours.builtin.theAuditorRecordsEachKeepDoneOr": "Der Prüfer protokolliert jedes Urteil (beibehalten, erledigt, festgefahren) mit Angabe der Begründung.",
  "packages.onboarding.tours.builtin.theAutoApproveToggleInTheSession": "Mit dem Schalter „Automatische Genehmigung“ in der Sitzungsüberschrift wird die automatische Genehmigung für die aktuelle oder die nächste Sitzung aktiviert. Um jede Aktion erneut zu überprüfen, muss der Schalter deaktiviert werden. Riskante Aktionen fragen immer nach.",
  "packages.onboarding.tours.builtin.theCapabilityListGivesAQuickView": "Die Funktionsliste bietet einen schnellen Überblick über die in dieser Laufzeitumgebung verfügbaren Funktionen.",
  "packages.onboarding.tours.builtin.theme": "Design",
  "packages.onboarding.tours.builtin.toggleTheProjectFilesPaneWithMod": "Mit Mod+Shift+E können Sie den Bereich „Projektdateien“ umschalten, um die Dateien zu durchsuchen und zu bearbeiten, ohne den aktiven Chat zu verlassen. Alternativ können Sie mit Mod+P von überall aus nach Dateien suchen.",
  "packages.onboarding.tours.builtin.toggleTheTerminalPaneWithModJ": "Mit Mod+J kann das Terminalfenster eingeblendet werden, ohne den Chat zu ersetzen. Anschließend kann zwischen unabhängig voneinander laufenden Tabs gewechselt werden.",
  "packages.onboarding.tours.builtin.tuneTheConversation": "Unterhaltung anpassen",
