  "settings.commandline.trustCaution": "In diesem Modus kann jedes Programm auf den erlaubten Rechnern – einschließlich hier ausgeführter Agenten – Polyth in Ihrem Namen steuern und Agentenaktionen genehmigen. Anfragen über einen Reverse-Proxy oder einen Browser werden niemals als vertrauenswürdig eingestuft. „Privates Netzwerk“ bezeichnet lokale IP-Adressen (10.x, 172.16–31.x, 192.168.x), keine VPN- oder Overlay-Netze.",
