  "shellintro.kicker": "Oberflächen-Tour",
  "shellintro.stepCount": "{step} von {total}",
  "shellintro.steps": "Tour-Schritte",
  "shellintro.goToStep": "Zu Schritt {step} von {total}",
  "shellintro.start": "Rundgang starten",
  "shellintro.skip": "Tour überspringen",
  "shellintro.finish": "Loslegen",
  "shellintro.menuEntry": "Oberflächen-Tour",
  "shellintro.addProjectNow": "Jetzt Projekt hinzufügen",
  "shellintro.addProjectResumeNote": "Die Tour geht weiter, sobald Sie fertig sind.",
  "shellintro.projectReadyTitle": "Ihr Projekt ist bereit",
  "shellintro.projectReadyBody": "Hier ist es. Solange es ausgewählt ist, können neue Chats seine Dateien sehen und damit arbeiten. Klicken Sie in dieser Liste auf ein Projekt, um zwischen Projekten zu wechseln.",
  "shellintro.projectReadyPhoneBody": "Es steht jetzt in diesem Menü. Solange es ausgewählt ist, können neue Chats seine Dateien sehen und damit arbeiten. Tippen Sie hier jederzeit, um das Projekt zu wechseln.",
  "shellintro.openAppearance": "Erscheinungsbild öffnen",
  "shellintro.welcomeTitle": "Willkommen bei Polyth",
  "shellintro.welcomeBody": "Sie können sofort loslegen – es gibt nichts einzurichten, und Sie können nichts kaputt machen. Diese einminütige Tour zeigt Ihnen, wo Sie schreiben, wo Ihre Chats gespeichert sind und wie Sie später etwas ändern.",
  "shellintro.startTitle": "Gleich hier loslegen",
  "shellintro.startBody": "Schreiben Sie in eigenen Worten, was Sie brauchen – eine Frage, eine Aufgabe oder einen Entwurf – und senden Sie es ab. Die Antwort erscheint genau hier. Ihre Chats sehen nur Sie.",
  "shellintro.projectsTitle": "Chats und Projekte",
  "shellintro.projectsBody": "Hier werden alle Ihre Chats aufbewahrt, sodass Sie zu jedem zurückkehren können. Projekte, die Sie später hinzufügen, erscheinen ebenfalls hier, jedes mit eigenen Chats. Ein kleiner Punkt bedeutet, dass der Assistent arbeitet oder auf Ihre Antwort wartet.",
  "shellintro.addProjectTitle": "Projekte, wenn Sie sie brauchen",
  "shellintro.addProjectBody": "Zum Starten brauchen Sie keins. Ein Projekt ist einfach ein Ordner mit Ihren Dateien – Dokumente, Fotos, eine Website oder Code. Fügen Sie eins hinzu, und der Assistent kann diese Dateien auf Wunsch öffnen und bearbeiten. (Entwickler können auch ein Git-Repository oder einen anderen Computer per SSH verbinden.)",
  "shellintro.topRailTitle": "Werkzeuge oben",
  "shellintro.topRailBody": "Schaltflächen für Ihre Werkzeuge. Jedes öffnet sich neben dem Chat, sodass das Gespräch sichtbar bleibt.",
  "shellintro.rightRailTitle": "Weitere Werkzeuge an der Seite",
  "shellintro.rightRailBody": "Weitere Werkzeuge, auch Erweiterungen, die Sie installieren. Jedes öffnet sich als Seitenpanel; ziehen Sie am Rand, um es breiter zu machen.",
  "shellintro.toolsTitle": "Werkzeuge",
  "shellintro.dragTitle": "Schaltflächen nach Wunsch platzieren",
  "shellintro.dragBody": "Ziehen Sie eine Schaltfläche, um sie in ihrer Leiste oder auf eine andere zu verschieben. Zum Entfernen ziehen Sie sie weg und lassen los – Sie können sie später wieder hinzufügen. Auf einem Touchscreen zuerst gedrückt halten.",
  "shellintro.customizeTitle": "Funktionen nach Ihren Wünschen",
  "shellintro.customizeBody": "Öffnen Sie das Menü, auf das der Pfeil zeigt, und schalten Sie den „Bearbeitungsmodus“ ein: Auf jedem Bereich des Bildschirms erscheint ein Stift, mit dem Sie Schaltflächen und Widgets hinzufügen, entfernen oder verschieben. In den Einstellungen finden Sie den Rest: Assistenten und KI-Modelle, Erweiterungen (Pakete) und Tastenkürzel.",
  "shellintro.appearanceTitle": "Aussehen nach Ihren Wünschen",
  "shellintro.appearanceBody": "Unter Einstellungen → Erscheinungsbild wählen Sie Farben, hellen oder dunklen Modus, Textgröße, Schriften, ein Hintergrundbild und mehr. Jedes Projekt kann auch ein eigenes Symbol bekommen.",
  "shellintro.projectsPhoneTitle": "Chats und Projekte",
  "shellintro.projectsPhoneBody": "Tippen Sie hier, um Ihre Chats zu sehen. Projekte, die Sie später hinzufügen, erscheinen ebenfalls hier. Ein kleiner Punkt bedeutet, dass der Assistent arbeitet oder auf Ihre Antwort wartet.",
  "shellintro.addProjectPhoneBody": "Zum Starten brauchen Sie keins. Ein Projekt ist einfach ein Ordner mit Ihren Dateien – Dokumente, Fotos, eine Website oder Code. Die Schaltfläche + in diesem Menü fügt eins hinzu; danach kann der Assistent diese Dateien auf Wunsch öffnen und bearbeiten.",
  "shellintro.toolsPhoneTitle": "Werkzeuge",
  "shellintro.toolsPhoneBody": "Hier liegen Ihre Werkzeuge. Jedes öffnet sich bildschirmfüllend; tippen Sie auf „Zurück“, um zum Chat zurückzukehren.",
  "shellintro.customizePhoneBody": "Auf einem Computer können Sie im „Bearbeitungsmodus“ Ihres Menüs Schaltflächen hinzufügen, entfernen oder verschieben. Auch hier lassen sich in den Einstellungen Assistenten und KI-Modelle, Erweiterungen (Pakete) und mehr wählen.",
  "composer.manageHarnesses": "Harnesses verwalten",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "Modelle kommen aus Ihren Harnesses",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth spricht über Agenten-Harnesses mit Modellen. Die kostenlosen Modelle von OpenCode funktionieren ohne Konto. Lieber Claude Code, Codex oder ein anderer Agent? Installieren und richten Sie Ihre Favoriten auf der Seite „Harnesses“ ein – ganz optional.",
  "packages.onboarding.tours.installed.openHarnesses": "Harnesses öffnen",
